package android.os; import java.util.*; public class Binder implements IBinder { private final List<DeathRecipient> deaths=new ArrayList<>(); public int links,unlinks; public void linkToDeath(DeathRecipient d,int flags){deaths.add(d);links++;} public boolean unlinkToDeath(DeathRecipient d,int flags){unlinks++;return deaths.remove(d);} public void kill(){var old=List.copyOf(deaths);deaths.clear();for(var d:old)d.binderDied();} }